test:
def test_total_value():
    p = {'name': 'Widget', 'price': 2.5, 'qty': 4}
    assert total_value(p) == 10.0, 'total_value must be price * qty'

def test_total_value_zero_qty():
    p = {'name': 'Gadget', 'price': 99.0, 'qty': 0}
    assert total_value(p) == 0.0, 'total_value with qty 0 must be 0'

def test_product_is_plain_dict_at_runtime():
    p = {'name': 'Widget', 'price': 1.0, 'qty': 1}
    assert isinstance(p, dict), 'a TypedDict instance is still a plain dict at runtime'
